float pmask1 = (z1<3);
rs1 += float2 (q1,q2);
rs2 += float2 (-q1,-q2);
float3 ret2 = tex2D(sampler_PEsticks2,2*rs1);
float3 ret3 = tex2D(sampler_PEsticks2,2*rs2);

ret = max(ret2*pmask1,ret3*pmask1);


}

